# Abstract products
class Button(ABC):
    @abstractmethod
    def render(self):
        pass

    @abstractmethod
    def click(self):
        pass

class Checkbox(ABC):
    @abstractmethod
    def render(self):
        pass

    @abstractmethod
    def toggle(self):
        pass

# Concrete Windows products
class WindowsButton(Button):
    def render(self):
        return "🪟 Rendering Windows-style button"

    def click(self):
        return "🖱️ Windows button clicked!"

class WindowsCheckbox(Checkbox):
    def __init__(self):
        self.checked = False

    def render(self):
        return "🪟 Rendering Windows-style checkbox"

    def toggle(self):
        self.checked = not self.checked
        return f"☑️ Windows checkbox: {'Checked' if self.checked else 'Unchecked'}"

# Concrete Mac products
class MacButton(Button):
    def render(self):
        return "🍎 Rendering Mac-style button"

    def click(self):
        return "🖱️ Mac button clicked!"

class MacCheckbox(Checkbox):
    def __init__(self):
        self.checked = False

    def render(self):
        return "🍎 Rendering Mac-style checkbox"

    def toggle(self):
        self.checked = not self.checked
        return f"☑️ Mac checkbox: {'Checked' if self.checked else 'Unchecked'}"

# Concrete Linux products
class LinuxButton(Button):
    def render(self):
        return "🐧 Rendering Linux-style button"

    def click(self):
        return "🖱️ Linux button clicked!"
