# Old payment system (Adaptee - incompatible interface)
class OldPaymentSystem:
    """Legacy payment system with different interface"""
    def make_payment(self, amount):
        return f"💰 Old system: Paid ${amount}"

# New payment interface (Target)
class PaymentProcessor(ABC):
    """New standard interface"""
    @abstractmethod
    def process(self, amount):
        pass

# Adapter
class PaymentAdapter(PaymentProcessor):
    """Adapts old system to new interface"""
    def __init__(self, old_system: OldPaymentSystem):
        self.old_system = old_system

    def process(self, amount):
        # Translate new interface call to old system call
        return self.old_system.make_payment(amount)

# New payment systems
class StripePayment(PaymentProcessor):
    def process(self, amount):
        return f"💳 Stripe: Processed ${amount}"

class PayPalPayment(PaymentProcessor):
    def process(self, amount):
        return f"🅿️ PayPal: Processed ${amount}"
