# Client code
class ECommerceSystem:
    """Client that works with PaymentProcessor interface"""
    def __init__(self):
        self.processors = []

    def add_processor(self, processor: PaymentProcessor):
        self.processors.append(processor)

    def checkout(self, amount):
        print(f"\n💵 Checkout: ${amount}")
        for processor in self.processors:
            print(f"   {processor.process(amount)}")

# Demo
print("\n🔍 Testing Adapter Pattern:")
ecommerce = ECommerceSystem()

# Add new payment systems
ecommerce.add_processor(StripePayment())
ecommerce.add_processor(PayPalPayment())

# Adapt old payment system to work with new interface
old_system = OldPaymentSystem()
adapted_old_system = PaymentAdapter(old_system)
ecommerce.add_processor(adapted_old_system)

# All work through same interface!
ecommerce.checkout(100)

print("\n✅ Old payment system works seamlessly with new interface!")

# Another example: Media players
print("\n\n🎵 Another Example - Media Player Adapter:")

class MP3Player:
    """Old format player"""
    def play_mp3(self, filename):
        return f"🎵 Playing MP3: {filename}"

class MediaPlayer(ABC):
    """New interface"""
    @abstractmethod
    def play(self, format_type, filename):
        pass

class MP4Player:
    def play_mp4(self, filename):
        return f"🎬 Playing MP4: {filename}"

class VLCPlayer:
    def play_vlc(self, filename):
        return f"📺 Playing VLC: {filename}"
