Adapter for different media formats

```python
class MediaAdapter(MediaPlayer):
    """Adapter for different media formats"""
    def __init__(self):
        self.mp3_player = MP3Player()
        self.mp4_player = MP4Player()
        self.vlc_player = VLCPlayer()

    def play(self, format_type, filename):
        if format_type == "mp3":
            return self.mp3_player.play_mp3(filename)
        elif format_type == "mp4":
            return self.mp4_player.play_mp4(filename)
        elif format_type == "vlc":
            return self.vlc_player.play_vlc(filename)
        else:
            return f"❌ Unsupported format: {format_type}"

# Use adapter
adapter = MediaAdapter()
print(adapter.play("mp3", "song.mp3"))
print(adapter.play("mp4", "movie.mp4"))
print(adapter.play("vlc", "video.vlc"))

